private static Map<TypeVariable<?>, Type> buildTypeVariableMap(ParameterizedType parameterizedType,
        Map<TypeVariable<?>, Type> typeVariableMap) {
    if (typeVariableMap == null) {
        typeVariableMap = new HashMap<>();
    }
    Type rawType = parameterizedType.getRawType();
    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
    TypeVariable<? extends Class<?>>[] typeVariables = ((Class<?>) rawType).getTypeParameters();
    for (int i = 0; i < typeVariables.length; i++) {
        TypeVariable<?> typeVariable = typeVariables[i];
        Type actualTypeArgument = actualTypeArguments[i];
        typeVariableMap.put(typeVariable, actualTypeArgument);
        if (actualTypeArgument instanceof ParameterizedType) {
            buildTypeVariableMap((ParameterizedType) actualTypeArgument, typeVariableMap);
        }
    }
    return typeVariableMap;
}

