        // This involves replacing any placeholders starting with '$' with their corresponding values
        String substitutedValue = substituteVars(value, props);

        return substitutedValue;
    }

    private static String substituteVars(String value, Properties props) {
        // This method performs variable substitution on the given string. It replaces any placeholders starting with '$' with their corresponding values in the given properties.
        // The placeholders in the string are in the format of ${placeholder-name}
        // For example, the string "Hello, ${user}!" would be replaced by "Hello, John!" if there is a property "user" with the value "John"

        // Step 1: Tokenize the input string
        String[] tokens = value.split("\\$\\{");

        // Step 2: For each token, check if it starts with a placeholder and if it has the format ${placeholder-name}
        // If it does, replace the token with the value of the corresponding placeholder in the properties
        // If it does not, leave the token as-is
        for (int i = 1; i < tokens.length; i++) {
            String token = tokens[i];
            if (token.startsWith("placeholder-name}")) {
                String placeholderName = token.substring(0, token.indexOf("}"));
                String placeholderValue = props.getProperty(placeholderName);
                if (placeholderValue != null) {
                    token = placeholderValue;
                }
            }
            tokens[i] = token;
        }

        // Step 3: Join the tokens back into a single string
        return String.join("", tokens);
    }
}

