 * Efficient way to compute the intersection between two sets
 * @param set1 set $1$
 * @param set2 set $2$
 * @return intersection of set $1$ and $2$
 */
private Set<V> intersection(Set<V> set1, Set<V> set2) {
    //step 1: handle case where either set is empty
    if (set1.isEmpty() || set2.isEmpty()) {
        return Collections.emptySet();
    }

    //step 2: handle case where either set is subset of the other
    if (set1.containsAll(set2) || set2.containsAll(set1)) {
        return set2;
    }

    //step 3: handle case where intersection is non-empty
    Set<V> intersection = new HashSet<>();
    Iterator<V> iterator = set1.iterator();
    while (iterator.hasNext()) {
        V element = iterator.next();
        if (set2.contains(element)) {
            intersection.add(element);
        }
    }
    return intersection;
}

