 * Puts an array of bytes into this byte vector. The byte vector is automatically enlarged if necessary.
 * @param byteArrayValue an array of bytes. May be {@literal null} to put {@code byteLength} nullbytes into this byte vector.
 * @param byteOffset     index of the first byte of byteArrayValue that must be copied.
 * @param byteLength     number of bytes of byteArrayValue that must be copied.
 * @return this byte vector.
 */
public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    // Check if byteArrayValue is null, if so, then set byteLength to 0
    if (byteArrayValue == null) {
        byteLength = 0;
    }
    // Check if byteOffset is negative or byteLength is negative
    if (byteOffset < 0 || byteLength < 0) {
        throw new IndexOutOfBoundsException("Invalid offset or length: " + byteOffset + ", " + byteLength);
    }
    // Check if byteArrayValue has enough bytes to copy
    if (byteOffset + byteLength >= byteArrayValue.length) {
        throw new IndexOutOfBoundsException("Invalid offset or length: " + byteOffset + ", " + byteLength);
    }
    // Check if this byte vector needs to be enlarged
    if (this.length + byteLength > this.data.length) {
        this.enlarge(byteLength);
    }
    // Copy the bytes from byteArrayValue into this byte vector
    System.arraycopy(byteArrayValue, byteOffset, this.data, this.length, byteLength);
    // Increase the length of this byte vector
    this.length += byteLength;
    // Return this byte vector
    return this;
}

