public GraphPath<V,E> edgeSetToTour( Set<E> tour, Graph<V,E> graph ){

//Create a graph path with the same vertices as the graph
GraphPath<V,E> path = new GraphPath<>( graph.vertexSet() );

//Get the vertices and edges from the set representation of the tour
Set<V> vertices = new HashSet<V>( graph.vertexSet() );
Set<E> edges = new HashSet<E>( graph.edgeSet() );

//Iterate through the set representation of the tour
for ( E edge : edges ){
    V u = graph.getEdgeSource( edge );
    V v = graph.getEdgeTarget( edge );

    //Get the index of the starting vertex in the graph vertex set
    int indexU = graph.vertexSet().indexOf( u );
    int indexV = graph.vertexSet().indexOf( v );

    //Add the edge to the graph path
    path.addEdge( indexU, indexV, edge );
}

return path;
}

